package com.agacostays.billing.storage.impl;
import com.agacostays.billing.entity.Bill;import com.agacostays.billing.exception.ResourceNotFoundException;import com.agacostays.billing.storage.InvoiceStorageService;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.nio.file.*;
@Service public class InvoiceStorageServiceImpl implements InvoiceStorageService{private final Path dir;private final String cur;public InvoiceStorageServiceImpl(@Value("${billing.storage.path}")String d,@Value("${billing.currency}")String c){dir=Paths.get(d);cur=c;}public String store(Bill b,String n){try{Files.createDirectories(dir);String t="AGA CoStays\nInvoice: "+n+"\nBill ID: "+b.getBillId()+"\nBooking ID: "+b.getBookingId()+"\nRoom Charges: "+b.getRoomCharges()+" "+cur+"\nRestaurant Charges: "+b.getRestaurantCharges()+" "+cur+"\nTax: "+b.getTaxAmount()+" "+cur+"\nDiscount: "+b.getDiscount()+" "+cur+"\nFinal Amount: "+b.getFinalAmount()+" "+cur+"\nPayment Status: "+b.getPaymentStatus()+"\n";Files.writeString(dir.resolve(n+".txt"),t,StandardCharsets.UTF_8);return "/api/invoices/NUMBER_PLACEHOLDER/download";}catch(Exception e){throw new IllegalStateException("Unable to store invoice",e);}}public byte[] read(String n){try{Path p=dir.resolve(n+".txt");if(!Files.exists(p))throw new ResourceNotFoundException("Invoice file not found");return Files.readAllBytes(p);}catch(ResourceNotFoundException e){throw e;}catch(Exception e){throw new IllegalStateException("Unable to read invoice",e);}}}
